def days_to_book_club(start, every, today):
    # Calculate the next meeting day that is on or after 'today'
    next_meeting = start + (today - start) // every * every
    if next_meeting < today:
        next_meeting += every
    return next_meeting - today

def days_to_book_club(start, every, today):
    # Calculate the next meeting day that is on or after today
    next_meeting = start + (today - start) // every * every
    if today > next_meeting:
        next_meeting += every
    return next_meeting - today
